trait Ord[T] {                                   // type class = strategy interface
  def compare(x: T, y: T): Int
}

given intOrd: Ord[Int] with {                    // ConcreteStrategy
  def compare(x: Int, y: Int) = x.compare(y)
}

def maximum[T](xs: List[T])(using ord: Ord[T]): T =   // Context uses it implicitly
  xs.reduceLeft((a, b) => if ord.compare(a, b) < 0 then b else a)
